// Engine 3 Excel writer. Input is generated by client.py after exact key/heading checks.
import fs from 'node:fs/promises';
import {Workbook,SpreadsheetFile} from '@oai/artifact-tool';
const [input,output]=process.argv.slice(2);
if(!input||!output) throw Error('Usage: node exporter.mjs prepared.json output.xlsx');
const data=JSON.parse(await fs.readFile(input,'utf8'));
if(data.sheets['Client Output'][0].length!==37) throw Error('37 headings required');
const wb=Workbook.create();
for(const [name,values] of Object.entries(data.sheets)) {
  const s=wb.worksheets.add(name); s.showGridLines=false;
  const width=values[0].length;
  if(values.some(r=>r.length!==width)) throw Error(`Ragged sheet ${name}`);
  const safe=values.map(r=>r.map(v=>typeof v==='string'&&v.startsWith('=')?"'"+v:v));
  s.getRangeByIndexes(0,0,values.length,width).values=safe;
  const all=s.getRangeByIndexes(0,0,values.length,width);
  all.format.font={name:'Arial',size:10}; all.format.columnWidth=24;
  all.format.rowHeight=58; all.format.verticalAlignment='center'; all.format.wrapText=true;
  s.getRangeByIndexes(0,0,values.length,1).format.columnWidth=44;
  const head=s.getRangeByIndexes(0,0,1,width);
  head.format.fill='#254B36'; head.format.font={name:'Arial',size:10,bold:true,color:'#FFFFFF'};
  head.format.wrapText=true; head.format.rowHeight=72;
  if(name!=='Client Output') {all.format.columnWidth=44; all.format.wrapText=true; all.format.rowHeight=58; head.format.rowHeight=36;}
  s.freezePanes.freezeRows(1);
}
wb.recalculate();
await fs.writeFile(output+'.inspect.json',(await wb.inspect({kind:'table',range:"'Client Output'!A1:D4",tableMaxRows:4,tableMaxCols:4})).ndjson);
const file=await SpreadsheetFile.exportXlsx(wb); await file.save(output);
// Previews are internal QA artifacts, not client scientific evidence.
for(const name of Object.keys(data.sheets)) {
 const preview=await wb.render({sheetName:name,range:name==='Client Output'?'A1:D5':'A1:C5',scale:1,format:'png'});
 await fs.writeFile(output+'.'+name.replaceAll(' ','_')+'.png',new Uint8Array(await preview.arrayBuffer()));
}
